<?php header("Access-Control-Allow-Origin: *");header("Access-Control-Allow-Headers: Content-Type");header("Access-Control-Allow-Methods: GET, POST, OPTIONS");header("Content-Type: application/json; charset=utf-8");if($_SERVER["REQUEST_METHOD"]==="OPTIONS"){http_response_code(204);exit;}require_once __DIR__."/config/database.php";$conn=db();function response_json($data,$status=200){http_response_code($status);echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit;}$cards=[["label"=>"Itens","value"=>$conn?count_table($conn,"armas"):0,"description"=>"Registros principais do sistema"],["label"=>"Categorias","value"=>$conn?count_table($conn,"categorias_armas"):0,"description"=>"Classificacoes cadastradas"],["label"=>"Acessorios","value"=>$conn?count_table($conn,"acessorios"):0,"description"=>"Complementos vinculados aos itens"],["label"=>"Ranking","value"=>$conn?count_table($conn,"ranking_armas"):0,"description"=>"Registros analiticos"]];$itens=[];if($conn&&table_exists($conn,"armas")){$sql="SELECT a.nome,COALESCE(c.nome_categoria,".chr(39)."Sem categoria".chr(39).") AS categoria,COALESCE(a.status_meta,".chr(39)."Estavel".chr(39).") AS status,COALESCE(a.taxa_uso,0) AS taxa_uso FROM armas a LEFT JOIN categorias_armas c ON c.id_categoria=a.id_categoria ORDER BY a.id_arma ASC LIMIT 8";$res=$conn->query($sql);if($res){while($row=$res->fetch_assoc()){$itens[]=["nome"=>$row["nome"],"categoria"=>$row["categoria"],"status"=>$row["status"],"taxa_uso"=>$row["taxa_uso"]."%"];}}}response_json(["api"=>"online","database"=>["connected"=>$conn!==null,"name"=>"esmerald_db"],"cards"=>$cards,"itens"=>$itens]); ?>